def decode_string(s):
    stack, cur, num = [], "", 0
    for ch in s:
        if ch.isdigit():
            num = num * 10 + int(ch)
        elif ch == "[":
            stack.append((cur, num))
            cur, num = "", 0
        elif ch == "]":
            outer, k = stack.pop()
            cur = outer + cur * k
        else:
            cur += ch
    return cur

def decode_string(s):
    def parse(i):
        out, num = [], 0
        while i < len(s) and s[i] != "]":
            ch = s[i]
            if ch.isdigit():
                num = num * 10 + int(ch)
                i += 1
            elif ch == "[":
                inner, i = parse(i + 1)
                out.append(inner * num)
                num = 0
                i += 1                         # skip the ']'
            else:
                out.append(ch)
                i += 1
        return "".join(out), i

    return parse(0)[0]
